from PIL import Image
import numpy as np
from scipy import ndimage
im=np.array(Image.open('/app/output/clear_scene_cam.png'))
# print ROI
for v in range(185,245,2):
 vals=[]
 for u in range(362,405):
  pix=im[v,u]
  if np.min(pix)<120 or (pix[0]<190 and pix[1]<180): vals.append((u,tuple(pix)))
 if vals: print(v,vals[::3])
# threshold local luminance and non-neutral color; wells dark enough
roi=im[185:245,360:410]
mask=(roi.mean(axis=2)<160)
l,n=ndimage.label(mask)
objs=[]
for sl in ndimage.find_objects(l):
 if sl:
  yy,xx=sl; area=(l[sl]==l[yy.start,xx.start]).sum()
  if area>3: objs.append((area,xx.start+360,yy.start+185,xx.stop+360,yy.stop+185))
print('components',sorted(objs,reverse=True)[:60])
PY

